// Incoming escalation payload from Axiom (POST body).
const payload = $input.first().json.body ?? $input.first().json;

// --- Notification (demo stub) ---
// In a real flow, replace this with a Slack or Email node.
console.log('AXIOM escalation:', payload.severity, payload.action?.type, '->', payload.link);

// --- Decision (demo auto-approve) ---
// Swap for real logic or a human-in-the-loop branch as needed.
const decision = {
  receipt_id: payload.receipt_id,
  decision: 'approved',
  reason: 'auto-approved by n8n demo workflow',
};

// Sign the EXACT bytes we will send, so the HMAC matches on the Axiom side.
const bodyString = JSON.stringify(decision);
const crypto = require('crypto');
const secret = $env.N8N_CALLBACK_SECRET || 'dev_escalation_secret_change_me';
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyString).digest('hex');

return [{ json: { callback_url: payload.callback_url, bodyString, signature } }];
